try {
  const resources = await tools.opencode.list_mcp_resources({});
  return { ok: true, resources };
} catch (e) {
  return { ok: false, error: String(e) };
}

// Page through the full catalog
let all = [];
let offset = 0;
while (true) {
  const page = search({ limit: 50, offset });
  all = all.concat(page.items.map(i => i.path));
  if (!page.next) break;
  offset = page.next.offset;
}
// Also try explicit namespaces
let nsChecks = [];
for (const ns of ["recon-echo", "recon_echo", "mcpreview", "recon"]) {
  try {
    const r = search({ namespace: ns });
    nsChecks.push({ ns, items: r.items.map(i => i.path) });
  } catch (e) {
    nsChecks.push({ ns, error: String(e) });
  }
}
return { totalFound: all.length, allPaths: all, echoOrRecon: all.filter(p => /echo|recon/i.test(p)), nsChecks };

const matches = [
  search({ query: "echo" }),
  search({ query: "recon" }),
  search({}),
];
return matches.map(m => ({ remaining: m.remaining, items: m.items.map(i => i.path) }));

const results = search({ query: "recon-echo echo" });
const tool = results.items.find(i => /echo/i.test(i.path) && /recon/i.test(i.path)) || results.items[0];
if (!tool) {
  return { error: "recon-echo MCP tool not found", results };
}
const out = await tools.recon_echo?.["echo"] ? await tools.recon_echo["echo"]({ text: "mcp-check" }) : null;
return { toolFound: tool.path, signature: tool.signature, echoResult: out, allItems: results.items };
